package ketch.wire

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

/**
 * One contract scenario under `desktop/contract/scenarios/`: a call, what the core said and asked while it ran, and
 * how it ended. The files are generated by the Rust tree's `crates/ketch-ffi/tests/contract.rs` and copied here
 * unchanged, so a fake core in the app and the real `ketch serve` are held to the same streams.
 */
@Serializable
data class Scenario(
    val name: String,
    val description: String,
    val call: Call,
    val script: List<ScriptStep>,
    val outcome: Outcome,
)

/** One thing that happens during a scenario's call, in order. */
@Serializable
sealed interface ScriptStep {
    @Serializable
    @SerialName("event")
    data class Reported(
        val event: Event,
    ) : ScriptStep

    /** A question and what a person answered when the scenario was written. */
    @Serializable
    @SerialName("ask")
    data class Ask(
        val question: Question,
        val answer: Answer,
    ) : ScriptStep
}
